// Typed access to src/data/slide-types.json - the slide-type registry as it
// exists in the core repo, generated by scripts/generate-slide-types.js.
//
// Everything here is derived. Nothing about a slide type is written down twice
// on this site: the count, the list, the labels, the field tables, the
// "when to use it" lines and the layout glyphs all come out of core. Editing this
// file cannot change what the site claims - regenerate instead.

import data from '@/data/slide-types.json';
import type { SchematicSpec } from '@/lib/schematic';

export interface SlideTypeField {
  key: string;
  label: string;
  type: string;
  required: boolean;
  maxLength?: number;
  options?: { value: string; label: string }[];
  itemFields?: SlideTypeField[];
}

export interface SlideTypeLayoutVariant {
  id: string;
  label: string;
  schematic: SchematicSpec | null;
}

export interface SlideType {
  /** Bare registry key, and the value in a deck's `slides[].type`. */
  name: string;
  /** Qualified identity: `namespace/name[@version]`. */
  id: string;
  label: string;
  deprecated: boolean;
  group: SlideTypeGroup;
  /** True when the audience takes part rather than only watching. */
  audience: boolean;
  description: string | null;
  agentDescription: string | null;
  bestFor: string[];
  notFor: string[];
  schematic: SchematicSpec | null;
  layoutVariants: SlideTypeLayoutVariant[];
  /** Type-specific fields. The nine every type carries are in `globalFields`. */
  fields: SlideTypeField[];
}

export type SlideTypeGroup = 'basic' | 'media' | 'layouts' | 'data' | 'interaction' | 'other';

/** Display order, matching the editor's own shelving. */
export const SLIDE_TYPE_GROUPS: SlideTypeGroup[] = [
  'basic',
  'media',
  'layouts',
  'data',
  'interaction',
  'other',
];

const registry = data as unknown as {
  count: number;
  activeCount: number;
  deprecatedCount: number;
  globalFields: SlideTypeField[];
  types: SlideType[];
};

export const slideTypes: SlideType[] = registry.types;
export const globalFields: SlideTypeField[] = registry.globalFields;

/** Built-in slide types in core. Excludes anything a fork adds locally. */
export const slideTypeCount = registry.count;
export const slideTypeActiveCount = registry.activeCount;
export const slideTypeDeprecatedCount = registry.deprecatedCount;

/** How many types let the audience take part - the figure that sets it apart. */
export const slideTypeAudienceCount = slideTypes.filter((t) => t.audience && !t.deprecated).length;

/** Active types in a group, in registration order. */
export function typesInGroup(group: SlideTypeGroup): SlideType[] {
  return slideTypes.filter((t) => t.group === group && !t.deprecated);
}

/** The four types kept only so existing decks keep rendering. */
export const deprecatedTypes: SlideType[] = slideTypes.filter((t) => t.deprecated);
